source.loginJs:
//登录
function login() {
	  let url = getUrl();
   let cookies = this.cookie.getCookie(url) || this.java.getCookie(url)
   if (cookies && cookies != "") {
     java.toast("\n请不要重复登录，请先退出登录！")
     return false
   }
   try {
     java.startBrowserAwait(url, "登录")
   } catch (e) {
     java.toast(e)
   }
   cookies = cookie.getCookie(url)
   if (!cookies || cookies == "") {
     java.toast("登录失败！")
     return false
   }
   java.toast("登录成功！")
   return true
}

//退出登录
function logout() {
   cookie.removeCookie(getUrl());
   let cookies = cookie.getCookie(url)
   if (cookies && cookies != "") {
     java.toast("退出登录失败！")
     return false
   }
   java.toast("成功退出登录！")
   return true
}

 var mode = ["❗小说模式❗","❗漫画模式❗","❗视频模式❗","❗听书模式❗"]

 //显示当前模式
var K = () => {
  let v = String(source.getVariable()).split(",");
  let x = v[0] || 0;
  java.toast("\n" + mode[x])
}

 //设置模式
var M = (x) => {
  let v = String(source.getVariable()).split(",");
  v[0] = x;
  source.setVariable(v.join(","));
  java.toast(`\n成功设置\n${mode[x]}`)
}

//显示当前域名
var H = () => {
  let v = String(source.getVariable()).split(",");
  let x = v[1] || 0;
	 java.toast(`\n当前域名:【${x}】\n${getUrl()}`)
}

//设置域名
var A = (x) => {
  let v = String(source.getVariable()).split(",");
  v[1] = x;
	 source.setVariable(v.join(","));
	 java.toast(`\n当前域名:【${v[1]}】\n${getUrl()}`)
}

