function b64Url(item_id) {
  const url =
    book.type === 32
      ? buildRequest(`http://115.190.42.251/fq/audio?item_id=${item_id.split("#")[1]}`)
      : `data:;base64,${java.base64Encode(item_id)},{"type":"pyfqc"}`;
  return String(url);
}

let type = +java.get("btype");
switch (type) {
  case 1:
    book.type = 64;
    break;
  case 4:
    book.type = 32;
    break;
  default:
    book.type = 8;
}
let bid = java.hexDecodeToString(result);
let list = [];
if (bid.includes("/")) {
  list.push({ title: "正文", url: b64Url(bid) });
} else {
  try {
    // 网页接口
    let u = "https://fanqienovel.com/api/reader/directory/detail?bookId=" + bid;
    java.log(u);
    let items = JSON.parse(java.ajax(u));
    let volms = new Set();
    let List = items.data.chapterListWithVolume;
    List.forEach(($) => {
      $.forEach((_, i) => {
        let name = _.volume_name || "";
        let time = java.timeFormat(_.firstPassTime * 1000);
        if (!i && book.type !== 32) list.push({ title: name, url: "", vo: true });
        list.push({ title: _.title, vo: false, url: b64Url(bid + "#" + _.itemId), info: `${name} | ${time}` });
      });
    });
    // throw new Error("api test");
  } catch (e) {
    java.log(e);
  }
}
list;

